using System;
using System.IO;
using Newtonsoft.Json;
using Xunit;
namespace RPCore.Tests
{
 public sealed class VehicleServiceTests
 {
  [Theory][InlineData(null,true)][InlineData("tanker",true)][InlineData("postop",true)][InlineData("uber",true)][InlineData("characters",false)][InlineData("inventory_use",false)][InlineData("homestorage",false)]
  public void RefuelingDoesNotRequireCancellingDrivingContractsButExcludesProtectedPersonalOperations(string activity,bool allowed)=>Assert.Equal(allowed,FuelOrder.ActivityAllows(activity));
  [Fact] public void FuelAndPaymentAdvanceOnlyAfterSaveAndKeepOdometer(){var tank=new FuelTank{Capacity=60,Liters=10,DistanceKm=123};var order=new FuelOrder(5,7);int cash=100,writes=0;Assert.True(order.Deliver(tank,3,()=>cash,v=>cash=v,()=>{writes++;Assert.Equal(13,tank.Liters);Assert.Equal(79,cash);}));Assert.Equal(3,order.Delivered);Assert.Equal(21,order.Paid);Assert.True(order.Deliver(tank,3,()=>cash,v=>cash=v,()=>writes++));Assert.True(order.Finished);Assert.Equal(15,tank.Liters);Assert.Equal(65,cash);Assert.Equal(35,order.Paid);Assert.Equal(123,tank.DistanceKm);Assert.Equal(2,writes);Assert.False(order.Deliver(tank,3,()=>cash,v=>throw new Exception(),()=>throw new Exception()));}
  [Fact] public void SmallPulsesBillCumulativeCeilingInsteadOfPerPulseSurcharge(){var tank=new FuelTank{Liters=0};var order=new FuelOrder(1,7);int cash=100;for(int i=0;i<10;i++)Assert.True(order.Deliver(tank,.1f,()=>cash,v=>cash=v,()=>{}));Assert.True(order.Finished);Assert.Equal(7,order.Paid);Assert.Equal(93,cash);Assert.InRange(tank.Liters,.99999f,1.00001f);}
  [Fact] public void AlreadyPaidRoundingCreditCanDeliverRemainingFractionWithZeroCash(){var tank=new FuelTank{Liters=0};var order=new FuelOrder(.14f,7);int cash=1;Assert.True(order.Deliver(tank,.1f,()=>cash,v=>cash=v,()=>{}));Assert.Equal(0,cash);Assert.True(order.Deliver(tank,.1f,()=>cash,v=>cash=v,()=>{}));Assert.Equal(1,order.Paid);Assert.True(order.Finished);Assert.InRange(tank.Liters,.13999f,.14001f);}
  [Fact] public void NoFundsOrPriorPaymentCannotCreateFuel(){var tank=new FuelTank{Liters=10};var order=new FuelOrder(5,7);Assert.False(order.Deliver(tank,3,()=>0,v=>throw new Exception(),()=>throw new Exception()));Assert.Equal(10,tank.Liters);Assert.Equal(0,order.Paid);}
  [Fact] public void SaveFailureRestoresCashFuelAndOrderWithoutRetryingACommittedPulse(){var tank=new FuelTank{Liters=10};var order=new FuelOrder(5,7);int cash=100;string before=JsonConvert.SerializeObject(tank);Assert.Throws<IOException>(()=>order.Deliver(tank,3,()=>cash,v=>cash=v,()=>throw new IOException()));Assert.Equal(before,JsonConvert.SerializeObject(tank));Assert.Equal(100,cash);Assert.Equal(0,order.Delivered);Assert.Equal(0,order.Paid);Assert.True(order.Deliver(tank,3,()=>cash,v=>cash=v,()=>{}));Assert.Equal(79,cash);}
  [Fact] public void NativeSetterFailingAfterWriteStillAttemptsExactCashRestore(){var tank=new FuelTank{Liters=10};var order=new FuelOrder(5,7);int cash=100,calls=0;Assert.Throws<IOException>(()=>order.Deliver(tank,3,()=>cash,v=>{cash=v;if(++calls==1)throw new IOException();},()=>throw new Exception()));Assert.Equal(100,cash);Assert.Equal(10,tank.Liters);Assert.Equal(0,order.Paid);}
  [Fact] public void UncertainRestoreSurfacesBothExceptionsAndNeverClaimsDelivery(){var tank=new FuelTank{Liters=10};var order=new FuelOrder(5,7);Assert.Throws<AggregateException>(()=>order.Deliver(tank,3,()=>100,v=>throw new IOException(),()=>{}));Assert.Equal(10,tank.Liters);Assert.Equal(0,order.Delivered);}
  [Fact] public void ReentrantSaveCannotRunSecondPulse(){var tank=new FuelTank{Liters=0};var order=new FuelOrder(5,7);int cash=100;Assert.True(order.Deliver(tank,3,()=>cash,v=>cash=v,()=>Assert.False(order.Deliver(tank,3,()=>cash,v=>throw new Exception(),()=>throw new Exception()))));Assert.Equal(3,order.Delivered);Assert.Equal(21,order.Paid);}
  [Theory][InlineData(.01f,1)][InlineData(.1f,7)][InlineData(1.37f,29)][InlineData(5,1000)] public void TotalPaidMatchesDeliveredAtCompletion(float requested,int price){var tank=new FuelTank{Liters=0};var order=new FuelOrder(requested,price);int cash=1000000;for(int i=0;i<2000 && !order.Finished;i++)Assert.True(order.Deliver(tank,.03f,()=>cash,v=>cash=v,()=>{}));Assert.True(order.Finished);Assert.Equal((int)Math.Ceiling((decimal)order.Delivered*price),order.Paid);Assert.Equal(1000000-order.Paid,cash);}
  [Fact] public void FullTankAndAffordabilityLimitEveryPulse(){var tank=new FuelTank{Capacity=60,Liters=59.5f};var order=new FuelOrder(10,7);int cash=2;Assert.True(order.Deliver(tank,3,()=>cash,v=>cash=v,()=>{}));Assert.InRange(tank.Liters,59.77f,59.79f);Assert.Equal(0,cash);Assert.False(order.Deliver(tank,3,()=>cash,v=>throw new Exception(),()=>throw new Exception()));}
  [Theory][InlineData("10,5",10.5f)][InlineData("10.50",10.5f)][InlineData("0,01",.01f)][InlineData("10000",10000f)] public void LitersAcceptTwoDecimalCommaOrDot(string text,float expected){Assert.True(FuelOrder.ParseLiters(text,out float value));Assert.Equal(expected,value);}
  [Theory][InlineData(null)][InlineData("")][InlineData("0")][InlineData("-1")][InlineData("1e3")][InlineData("1.000")][InlineData("10,123")][InlineData("10001")][InlineData("1,2.3")]
  public void InvalidAmountsCannotOpenOrder(string text)=>Assert.False(FuelOrder.ParseLiters(text,out _));
  [Theory][InlineData(float.NaN)][InlineData(float.PositiveInfinity)][InlineData(-1)][InlineData(0)] public void InvalidRequestedFuelRefused(float value){Assert.Throws<ArgumentOutOfRangeException>(()=>new FuelOrder(value,7));}
  [Fact] public void ExtremeStepCannotOverflowAndPriceCannotBeInvalid(){var order=new FuelOrder(1,7);Assert.Equal(1,order.Next(float.MaxValue,float.MaxValue,int.MaxValue).Liters);Assert.Throws<ArgumentOutOfRangeException>(()=>new FuelOrder(1,0));Assert.Throws<ArgumentOutOfRangeException>(()=>new FuelOrder(1,1001));}
  [Fact] public void ReceiptDoesNotContinueAfterOrderObjectIsDiscarded(){var a=new FuelOrder(5,7);var tank=new FuelTank{Liters=0};int cash=100;a.Deliver(tank,1,()=>cash,v=>cash=v,()=>{});string save=JsonConvert.SerializeObject(tank);var reloaded=JsonConvert.DeserializeObject<FuelTank>(save);Assert.Equal(tank.Liters,reloaded.Liters);Assert.Equal(93,cash);}
  [Fact] public void VehicleSessionRequiresSameProfileActorModelPointerCarAndPlate(){var id=new VehicleServiceIdentity("Franklin",1,2,3,4,5,6,"5:ABC");Assert.True(id.Matches("Franklin",1,2,3,4,5,6,"5:ABC"));Assert.False(id.Matches("Other",1,2,3,4,5,6,"5:ABC"));Assert.False(id.Matches("Franklin",7,2,3,4,5,6,"5:ABC"));Assert.False(id.Matches("Franklin",1,2,8,4,5,6,"5:ABC"));Assert.False(id.Matches("Franklin",1,2,3,4,5,8,"5:ABC"));Assert.False(id.Matches("Franklin",1,2,3,4,5,6,"5:NEW"));Assert.True(id.OwnsActor(1,2,3));Assert.False(id.OwnsActor(1,2,4));}
  [Theory][InlineData(true)][InlineData(false)] public void BeltRestoresItsPriorFlagOnlyOnSameActorAndOwnOverride(bool original){var flag=new SeatbeltOverride(original);Assert.False(flag.CanRestore(true,false));flag.Applied();Assert.True(flag.CanRestore(true,false));Assert.False(flag.CanRestore(false,false));Assert.False(flag.CanRestore(true,true));Assert.Equal(original,flag.Original);}
 }
}
